InterfaceAsPlainText.xhtml:
FUNCTION_BLOCK FB_DriveSupplyMgr
VAR_INPUT
    itfClient       : I_StateClient;    // GVL_State.aClients[GVL_State.CLIENT_DRIVE_HW]
    eMachineState : E_MachineState;   // machine state to follow (from the caller: the broadcast, or a sub-manager's state)
    wSupplyStatus   : WORD;             // supply unit status word S-0-2058 (S-0-1720.0.2)
END_VAR
VAR_IN_OUT
    wSupplyCtrl     : WORD;             // supply unit control word S-0-2057 (S-0-1720.0.1)
    awDriveStatus   : ARRAY[*] OF WORD; // drive status words, one per drive
    awDriveDcBusCtrl: ARRAY[*] OF WORD; // drive DC bus power control S-0-0240, one per drive
END_VAR
VAR_OUTPUT
    bSupplyInOperation : BOOL;          // diag: supply in operation mode (DC bus up)
    bSupplyOff      : BOOL;             // diag: supply mains off
    bAllReadyForPower : BOOL;           // diag: every drive ready for power
    bAnyUnderTorque : BOOL;             // diag: some drive under torque
    bAnyDriveFault  : BOOL;             // diag: some drive faulted
    bSupplyFault    : BOOL;             // diag: supply internal error or supply control error
    uiAbortCode     : UINT;             // abort code currently requested, 0 = none
END_VAR
VAR
    _eMachineState  : E_MachineState;   // eMachineState, read once per scan
    _stDrive        : ST_DriveFeedback;
    _bAllReady      : BOOL;
    _bAnyTorque     : BOOL;
    _bAnyDriveFault : BOOL;
    _iFirstFaultDrive : DINT;
    _iDrive         : DINT;
    _bSupplyInOp    : BOOL;
    _bSupplyOff     : BOOL;
    _bSupplyError   : BOOL;             // internal supply unit error
    _bSupplyCtrlError : BOOL;           // supply control FB error (invalid input, mode timeout)

    _bFaultAbortActive : BOOL;          // fault aborts are raised in this state
    _bAbort         : BOOL;
    _uiAbortCode    : UINT;
    _bDone          : BOOL;

    _bWantOn        : BOOL;
    _bSupplyCmd     : BOOL;             // supply to operation (self-holding)
    _bSupplyEnable  : BOOL;
    _eTargetMode    : MB_POWERSUPPLY_TARGET_MODE;

    _fbSupply       : MB_PowerSupplyDriveIntegrated;
    _fbStateReq     : FB_StateRequest;
END_VAR
VAR CONSTANT
    MASK_DC_BUS_POWER   : WORD := 16#0001;  // S-0-0240 bit 0: DC bus power enabled
    NO_DRIVE            : DINT := -1;     // drives are numbered from 0
    SUPPLY_MODE_TIMEOUT : TIME := T#10S;    // max time per supply mode change (supervised by the FB)
    ABORT_NONE          : UINT := 0;
    ABORT_SUPPLY_CTRL   : UINT := 100;      // supply did not reach its target mode / invalid input
    ABORT_SUPPLY_FAULT  : UINT := 101;      // supply unit internal error
    ABORT_DRIVE_FAULT   : UINT := 110;      // + drive index
END_VAR

ST.xhtml:
_eMachineState := eMachineState;     // read once per scan

// ===== 1. Read status =====
_bAllReady        := TRUE;
_bAnyTorque       := FALSE;
_bAnyDriveFault   := FALSE;
_iFirstFaultDrive := NO_DRIVE;
FOR _iDrive := LOWER_BOUND(awDriveStatus, 1) TO UPPER_BOUND(awDriveStatus, 1) DO
    _stDrive := Fn_DriveFeedback(wStatus := awDriveStatus[_iDrive]);
    _bAllReady  := _bAllReady AND _stDrive.bReadyForPower;
    _bAnyTorque := _bAnyTorque OR _stDrive.bUnderTorque;
    IF _stDrive.bFault THEN
        _bAnyDriveFault := TRUE;
        IF _iFirstFaultDrive = NO_DRIVE THEN
            _iFirstFaultDrive := _iDrive;
        END_IF
    END_IF
END_FOR

// Supply state from the previous call of the supply FB
_bSupplyInOp      := _fbSupply.ActualMode = MB_POWERSUPPLY_ACTUAL_MODE.OPERATION_MODE;
_bSupplyOff       := _fbSupply.ActualMode = MB_POWERSUPPLY_ACTUAL_MODE.MAINS_OFF;
_bSupplyError     := _fbSupply.PowerSupplyError;
_bSupplyCtrlError := _fbSupply.Error;

// ===== 2. Faults -> abort request =====
// Not raised while aborting, aborted or resetting: a fault that is still present must not
// block the reset that clears it. A fault that survives the reset leaves this client not
// done, and the manager's Resetting timeout aborts again.
_bFaultAbortActive := _eMachineState <> E_MachineState.Aborting
                      AND _eMachineState <> E_MachineState.Aborted
                      AND _eMachineState <> E_MachineState.Resetting;

_uiAbortCode := ABORT_NONE;
IF _bSupplyError THEN
    _uiAbortCode := ABORT_SUPPLY_FAULT;
ELSIF _bAnyDriveFault THEN
    _uiAbortCode := ABORT_DRIVE_FAULT + DINT_TO_UINT(_iFirstFaultDrive);
ELSIF _bSupplyCtrlError THEN
    _uiAbortCode := ABORT_SUPPLY_CTRL;
END_IF
_bAbort := _bFaultAbortActive AND _uiAbortCode <> ABORT_NONE;

// ===== 3. Done for the current machine state =====
CASE _eMachineState OF
    E_MachineState.Off:
        _bDone := NOT _bSupplyCmd AND _bSupplyOff;

    E_MachineState.TurningOn:
        _bDone := _bSupplyInOp;

    E_MachineState.Aborting:
        _bDone := NOT _bAnyTorque AND NOT _bSupplyCmd AND _bSupplyOff;

    E_MachineState.Resetting:
        _bDone := NOT _bSupplyError AND NOT _bSupplyCtrlError AND NOT _bAnyDriveFault AND _bSupplyInOp;

ELSE
    _bDone := TRUE;     // nothing to do beyond holding the supply state
END_CASE

// ===== 4. Command levels =====
_bWantOn := _eMachineState <> E_MachineState.Off
            AND _eMachineState <> E_MachineState.Aborted
            AND _eMachineState <> E_MachineState.Aborting;

// Switch on only when every drive is ready, then hold; never switch off under torque
_bSupplyCmd := (_bWantOn AND (_bSupplyCmd OR _bAllReady))
               OR (_bSupplyCmd AND _bAnyTorque);

IF _bSupplyCmd THEN
    _eTargetMode := MB_POWERSUPPLY_TARGET_MODE.OPERATION_MODE;
ELSE
    _eTargetMode := MB_POWERSUPPLY_TARGET_MODE.MAINS_OFF_NO_DISCHARGE;
END_IF

// Keep the FB enabled until the supply is really off. In Resetting, a supply control error
// holds Enable off, which is the documented way to clear the FB's error.
_bSupplyEnable := (_bSupplyCmd OR NOT _bSupplyOff)
                  AND NOT (_eMachineState = E_MachineState.Resetting AND _bSupplyCtrlError);

// DC bus power to every drive while the supply is in operation
FOR _iDrive := LOWER_BOUND(awDriveDcBusCtrl, 1) TO UPPER_BOUND(awDriveDcBusCtrl, 1) DO
    IF _bSupplyInOp THEN
        awDriveDcBusCtrl[_iDrive] := awDriveDcBusCtrl[_iDrive] OR MASK_DC_BUS_POWER;
    ELSE
        awDriveDcBusCtrl[_iDrive] := awDriveDcBusCtrl[_iDrive] AND NOT MASK_DC_BUS_POWER;
    END_IF
END_FOR

// ===== 5. Outputs, then sub-FBs =====
bSupplyInOperation := _bSupplyInOp;
bSupplyOff         := _bSupplyOff;
bAllReadyForPower  := _bAllReady;
bAnyUnderTorque    := _bAnyTorque;
bAnyDriveFault     := _bAnyDriveFault;
bSupplyFault       := _bSupplyError OR _bSupplyCtrlError;
uiAbortCode        := _uiAbortCode;

_fbSupply(
    Enable       := _bSupplyEnable,
    TargetMode   := _eTargetMode,
    Timeout      := SUPPLY_MODE_TIMEOUT,
    InProcStatus := wSupplyStatus,
    OutProcCtrl  := wSupplyCtrl);
_fbStateReq(
    itfClient   := itfClient,
    bAbort      := _bAbort,
    uiAbortCode := _uiAbortCode,
    eStateEcho  := _eMachineState,
    bDone       := _bDone);

Fn_DriveFeedback.bReadyForPower := (wStatus AND (MASK_BIT_14 OR MASK_BIT_15)) <> 0;
Fn_DriveFeedback.bUnderTorque   := (wStatus AND (MASK_BIT_14 OR MASK_BIT_15)) = (MASK_BIT_14 OR MASK_BIT_15);
Fn_DriveFeedback.bFault         := (wStatus AND MASK_FAULT) <> 0;

// ----- Axis status from the Data Layer RT -----
// The map FB opens the node and builds the config; each reader then reads one axis.
// A reader failure (last scan) makes the map FB close, reopen and remap.
fbAxisRtMap(
    bEnable    := TRUE,
    bReadFault := bAxisRtReadFault,
    asAxisName := GVL_Axes.asAxisName,
    fbMem      := fbRtMem,
    stConfig   := stAxisRtConfig);
bAxisRtReadFault := FALSE;
FOR iAxis := 0 TO GVL_Axes.LAST_AXIS DO
    afbAxisRtRead[iAxis](
        iAxis     := iAxis,
        fbMem     := fbRtMem,
        stConfig  := stAxisRtConfig,
        astStatus := GVL_Axes.astStatus);
    bAxisRtReadFault := bAxisRtReadFault OR afbAxisRtRead[iAxis].bError;
END_FOR

// ----- State manager and broadcast -----
fbStateManager(aClients := GVL_State.aClients);

GVL_State.eMachineState       := fbStateManager.eMachineState;
GVL_State.uiAbortCode         := fbStateManager.uiAbortCode;
GVL_State.iAbortClient        := fbStateManager.iAbortClient;
GVL_State.eAbortFrom          := fbStateManager.eAbortFrom;
GVL_State.bAbortUnacked       := fbStateManager.bAbortUnacked;
GVL_State.iAbortTimeoutClient := fbStateManager.iAbortTimeoutClient;
GVL_State.iNotDoneClient      := fbStateManager.iNotDoneClient;

// ----- HMI client: requests only, always done -----
fbHmiStateReq(
    itfClient   := GVL_State.aClients[GVL_State.CLIENT_HMI],
    bOn         := GVL_Hmi.bOnCmd,
    bOff        := GVL_Hmi.bOffCmd,
    bStart      := GVL_Hmi.bStartCmd,
    bStop       := GVL_Hmi.bStopCmd,
    bHold       := GVL_Hmi.bHoldCmd,
    bAbort      := GVL_Hmi.bAbortCmd,
    uiAbortCode := HMI_ABORT_CODE,
    bReset      := GVL_Hmi.bResetCmd,
    eStateEcho  := GVL_State.eMachineState,
    bDone       := TRUE);

// ----- Drive hardware station -----
fbDriveSupply(
    itfClient        := GVL_State.aClients[GVL_State.CLIENT_DRIVE_HW],
    eMachineState    := GVL_State.eMachineState,
    wSupplyStatus    := GVL_IO.wDI_SupplyStatus,
    wSupplyCtrl      := GVL_IO.wDO_SupplyCtrl,
    awDriveStatus    := GVL_IO.awDI_DriveStatus,
    awDriveDcBusCtrl := GVL_IO.awDO_DriveDcBusCtrl);

// ----- Servo station -----
fbServoAxes(
    itfClient     := GVL_State.aClients[GVL_State.CLIENT_SERVO_AXES],
    eMachineState := GVL_State.eMachineState,
    asAxisName    := GVL_Axes.asAxisName,
    astStatus     := GVL_Axes.astStatus);
fbServoMotion(
    itfClient     := GVL_State.aClients[GVL_State.CLIENT_SERVO_MOTION],
    eMachineState := GVL_State.eMachineState,
    asAxisName    := GVL_Axes.asAxisName,
    lrSpeedCmd    := GVL_Hmi.lrSpeedCmd,
    lrAx1Offset   := GVL_Hmi.lrSlaveOffset,
    lrAx2Offset   := MODULO - GVL_Hmi.lrSlaveOffset,
    astStatus     := GVL_Axes.astStatus);

IF bActive AND bAccepted THEN
    _stQuery.In.ObjName := sObjName;
    _stQuery.In.CmdID   := ulCmdID;
    _bQueryOk := ML_GetCmdState(Data := _stQuery);
    _bDone    := _bQueryOk AND NOT _stQuery.Out.Error AND _stQuery.Out.State = CMD_DONE;
    _bFailed  := NOT _bQueryOk OR _stQuery.Out.Error OR _stQuery.Out.State = CMD_ABORTED;
ELSE
    // Inactive: nothing to report. Active but rejected: failed straight away.
    _stQuery.Out.State := '';
    _bDone   := FALSE;
    _bFailed := bActive AND NOT bAccepted;
END_IF

// Outputs
bDone   := _bDone;
bFailed := _bFailed;
sState  := _stQuery.Out.State;

InterfaceAsPlainText.xhtml:
FUNCTION_BLOCK FB_AxisRtMap
VAR_INPUT
    bEnable         : BOOL;     // open the node, read the map and keep stConfig valid
    bReadFault      : BOOL;     // a reader failed: close, then reopen and reread the map after RETRY_DELAY
    asAxisName      : ARRAY[0..GVL_Axes.LAST_AXIS] OF STRING(15);    // ctrlX MOTION axis names, indexed like GVL_Axes
END_VAR
VAR_OUTPUT
    bReady          : BOOL;     // stConfig is valid
    bError          : BOOL;     // faulted, retrying every RETRY_DELAY
    bAllAxesFound   : BOOL;     // diag: every axis had every field in the map
    uiErrorStep     : UINT;     // diag: first failure: 1 open, 2 get map, 3 a reader failed (0 = none)
    eResult         : DL_RESULT;    // diag: Data Layer result of the first failure
    udiVarCount     : UDINT;    // diag: entries in the map
    udiRevision     : UDINT;    // diag: map revision
END_VAR
VAR_IN_OUT
    fbMem           : DL_MemUser;       // shared with the FB_AxisRtRead instances
    stConfig        : ST_AxisRtConfig;  // read configuration for FB_AxisRtRead
END_VAR
VAR
    _uiStep         : UINT;
    _uiLastStep     : UINT;
    _bOpen          : BOOL;             // OpenMemory was called: CloseMemory is due
    _eOpen          : DL_RESULT := DL_RESULT.DL_OK;
    _eGetMap        : DL_RESULT := DL_RESULT.DL_OK;
    _uiErrorStep    : UINT;
    _eResult        : DL_RESULT := DL_RESULT.DL_OK;
    _stConfig       : ST_AxisRtConfig;
    _stCleared      : ST_AxisRtConfig;  // never written: all FALSE / 0
    _bAllAxesFound  : BOOL;

    // Map parsing
    _fbMapNode      : DL_NODEVALUE;
    _fbMemMap       : comm_datalayer_MemoryMap;
    _fbVar          : comm_datalayer_Variable;
    _udiVarCount    : UDINT;
    _udiVar         : UDINT;
    _sName          : STRING(255);
    _sAxis          : STRING(255);
    _sField         : STRING(255);
    _iSep           : INT;
    _udiBitOffset   : UDINT;
    _iAxis          : INT;
    _iField         : INT;

    _fbRetry        : TON;
END_VAR
VAR CONSTANT
    STEP_IDLE       : UINT := 0;    // node closed, config invalid
    STEP_OPEN       : UINT := 1;    // OpenMemory issued on entry
    STEP_GET_MAP    : UINT := 2;    // map read and parsed on entry
    STEP_READY      : UINT := 3;    // config valid, readers read
    STEP_FAULT      : UINT := 4;    // node closed, waiting to retry
    ERROR_NONE      : UINT := 0;
    ERROR_OPEN      : UINT := 1;
    ERROR_GET_MAP   : UINT := 2;
    ERROR_READ      : UINT := 3;
    RETRY_DELAY     : TIME := T#1S; // time in Fault before the node is reopened
END_VAR

ST.xhtml:
// ===== 1. Jumps =====
IF _uiStep = STEP_OPEN AND _eOpen <> DL_RESULT.DL_OK THEN
    IF _uiErrorStep = ERROR_NONE THEN
        _uiErrorStep := ERROR_OPEN;
        _eResult     := _eOpen;
    END_IF
    _uiStep := STEP_FAULT;
ELSIF _uiStep = STEP_GET_MAP AND _eGetMap <> DL_RESULT.DL_OK THEN
    IF _uiErrorStep = ERROR_NONE THEN
        _uiErrorStep := ERROR_GET_MAP;
        _eResult     := _eGetMap;
    END_IF
    _uiStep := STEP_FAULT;
ELSIF _uiStep = STEP_READY AND bReadFault THEN
    IF _uiErrorStep = ERROR_NONE THEN
        _uiErrorStep := ERROR_READ;
    END_IF
    _uiStep := STEP_FAULT;
END_IF

// ===== 2. Transitions =====
CASE _uiStep OF
    STEP_IDLE:
        IF bEnable THEN
            _uiStep := STEP_OPEN;
        END_IF

    STEP_OPEN:
        // A failed open has already jumped to Fault
        IF NOT bEnable THEN
            _uiStep := STEP_IDLE;
        ELSE
            _uiStep := STEP_GET_MAP;
        END_IF

    STEP_GET_MAP:
        // A failed map read has already jumped to Fault
        IF NOT bEnable THEN
            _uiStep := STEP_IDLE;
        ELSE
            _uiStep := STEP_READY;
        END_IF

    STEP_READY:
        IF NOT bEnable THEN
            _uiStep := STEP_IDLE;
        END_IF

    STEP_FAULT:
        IF NOT bEnable THEN
            _uiStep := STEP_IDLE;
        ELSIF _fbRetry.Q THEN
            _uiStep := STEP_OPEN;
        END_IF

ELSE
    _uiStep := STEP_FAULT;
END_CASE

// ===== 3. On change =====
IF _uiStep <> _uiLastStep THEN
    // Common: the config is only valid in Ready
    _stConfig.bValid := _uiStep = STEP_READY;

    CASE _uiStep OF
        STEP_IDLE:
            IF _bOpen THEN
                fbMem.CloseMemory();
                _bOpen := FALSE;
            END_IF
            _stConfig    := _stCleared;
            _uiErrorStep := ERROR_NONE;
            _eResult     := DL_RESULT.DL_OK;

        STEP_OPEN:
            _eOpen := fbMem.OpenMemory(GVL_AxisRtMap.NODE_NAME);
            _bOpen := TRUE;     // close even after a failed open, as the Rexroth example does

        STEP_GET_MAP:
            _stConfig := _stCleared;
            _eGetMap  := fbMem.GetMemoryMap(_fbMapNode);
            IF _eGetMap = DL_RESULT.DL_OK THEN
                _fbMemMap.getRootAsMemoryMap(_fbMapNode.GetData(), _fbMapNode.GetSize());
                _udiVarCount := _fbMemMap.getVariablesLength();
                _udiVar := 0;
                // Bounded by the map size: one pass over the entries, in this scan
                WHILE _udiVar < _udiVarCount DO
                    _fbMemMap.getVariables(_udiVar, ADR(_fbVar));
                    _sName := _fbVar.getName();
                    _iSep  := FIND(_sName, GVL_AxisRtMap.NAME_SEPARATOR);
                    IF _iSep > 1 THEN
                        _sAxis        := LEFT(_sName, _iSep - 1);
                        _sField       := MID(_sName, LEN(_sName) - _iSep, _iSep + 1);
                        _udiBitOffset := _fbVar.getBitoffset();
                        FOR _iAxis := 0 TO GVL_Axes.LAST_AXIS DO
                            IF asAxisName[_iAxis] = _sAxis THEN
                                FOR _iField := 0 TO GVL_AxisRtMap.LAST_FIELD DO
                                    IF GVL_AxisRtMap.asFieldName[_iField] = _sField THEN
                                        _stConfig.astAxis[_iAxis].audiOffset[_iField] := _udiBitOffset / GVL_AxisRtMap.BITS_PER_BYTE;
                                        _stConfig.astAxis[_iAxis].abFound[_iField]    := _udiBitOffset MOD GVL_AxisRtMap.BITS_PER_BYTE = 0;
                                    END_IF
                                END_FOR
                            END_IF
                        END_FOR
                    END_IF
                    _udiVar := _udiVar + 1;
                END_WHILE
                _stConfig.udiRevision := _fbMemMap.getRevision();

                // An axis can be read only if every field was found
                _bAllAxesFound := TRUE;
                FOR _iAxis := 0 TO GVL_Axes.LAST_AXIS DO
                    _stConfig.astAxis[_iAxis].bComplete := TRUE;
                    FOR _iField := 0 TO GVL_AxisRtMap.LAST_FIELD DO
                        _stConfig.astAxis[_iAxis].bComplete := _stConfig.astAxis[_iAxis].bComplete
                                                               AND _stConfig.astAxis[_iAxis].abFound[_iField];
                    END_FOR
                    _bAllAxesFound := _bAllAxesFound AND _stConfig.astAxis[_iAxis].bComplete;
                END_FOR
            END_IF

        STEP_FAULT:
            IF _bOpen THEN
                fbMem.CloseMemory();
                _bOpen := FALSE;
            END_IF
            _stConfig := _stCleared;
    END_CASE
    _uiLastStep := _uiStep;
END_IF

// ===== 4. Cyclic =====
_fbRetry(IN := _uiStep = STEP_FAULT, PT := RETRY_DELAY);

// Outputs
stConfig      := _stConfig;
bReady        := _uiStep = STEP_READY;
bError        := _uiErrorStep <> ERROR_NONE AND _uiStep <> STEP_READY;
bAllAxesFound := _bAllAxesFound;
uiErrorStep   := _uiErrorStep;
eResult       := _eResult;
udiVarCount   := _udiVarCount;
udiRevision   := _stConfig.udiRevision;

_bIndexOk  := iAxis >= 0 AND iAxis <= GVL_Axes.LAST_AXIS;
_bValid    := FALSE;
_bError    := FALSE;
_bNotInMap := FALSE;
_eResult   := DL_RESULT.DL_OK;

IF stConfig.bValid AND _bIndexOk THEN
    _stOfs := stConfig.astAxis[iAxis];
    _bNotInMap := NOT _stOfs.bComplete;
    IF _stOfs.bComplete THEN
        // BeginAccess locks the buffer against other users, so EndAccess always follows,
        // with only the copy in between.
        _eResult := fbMem.BeginAccess(Data => _pData, Revision := stConfig.udiRevision);
        IF _eResult = DL_RESULT.DL_OK THEN
            fbMem.GetSize(SizeBytes => _udiSize);
            // Every field is copied; any copy outside the buffer fails the whole read
            _bCopyOk := TRUE;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_DATA_VALID],              pDst := ADR(_stStatus.DataValid),           udiSize := SIZEOF(_stStatus.DataValid)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_HOMED],                   pDst := ADR(_stStatus.Homed),               udiSize := SIZEOF(_stStatus.Homed)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_STANDSTILL],              pDst := ADR(_stStatus.Standstill),          udiSize := SIZEOF(_stStatus.Standstill)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_POWER_READY],             pDst := ADR(_stStatus.PowerReady),          udiSize := SIZEOF(_stStatus.PowerReady)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_POWER_ON],                pDst := ADR(_stStatus.PowerOn),             udiSize := SIZEOF(_stStatus.PowerOn)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_HAS_ERROR],               pDst := ADR(_stStatus.HasError),            udiSize := SIZEOF(_stStatus.HasError)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_HAS_WARNING],             pDst := ADR(_stStatus.HasWarning),          udiSize := SIZEOF(_stStatus.HasWarning)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_AXIS_FOLLOW_COMMAND],     pDst := ADR(_stStatus.AxisFollowCommand),   udiSize := SIZEOF(_stStatus.AxisFollowCommand)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_IN_POSITION],             pDst := ADR(_stStatus.InPosition),          udiSize := SIZEOF(_stStatus.InPosition)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_IN_VELOCITY],             pDst := ADR(_stStatus.InVelocity),          udiSize := SIZEOF(_stStatus.InVelocity)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_IN_TORQUE],               pDst := ADR(_stStatus.InTorque),            udiSize := SIZEOF(_stStatus.InTorque)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_IN_SYNC_WINDOW],          pDst := ADR(_stStatus.InSyncWindow),        udiSize := SIZEOF(_stStatus.InSyncWindow)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_IN_SYNCHRONIZATION],      pDst := ADR(_stStatus.InSynchronization),   udiSize := SIZEOF(_stStatus.InSynchronization)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_OVERRIDE_IS_ZERO],        pDst := ADR(_stStatus.OverrideIsZero),      udiSize := SIZEOF(_stStatus.OverrideIsZero)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_TORQUE_CTRL_POS_VEL_LIM], pDst := ADR(_stStatus.TorqueCtrlPosVelLim), udiSize := SIZEOF(_stStatus.TorqueCtrlPosVelLim)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_TORQUE_CTRL_NEG_VEL_LIM], pDst := ADR(_stStatus.TorqueCtrlNegVelLim), udiSize := SIZEOF(_stStatus.TorqueCtrlNegVelLim)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_ACTUAL_POS],              pDst := ADR(_stStatus.ActualPos),           udiSize := SIZEOF(_stStatus.ActualPos)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_ACTUAL_VEL],              pDst := ADR(_stStatus.ActualVel),           udiSize := SIZEOF(_stStatus.ActualVel)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_ACTUAL_TRQ],              pDst := ADR(_stStatus.ActualTRQ),           udiSize := SIZEOF(_stStatus.ActualTRQ)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_ACTUAL_TRQ_PERCENT],      pDst := ADR(_stStatus.ActualTRQPercent),    udiSize := SIZEOF(_stStatus.ActualTRQPercent)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_DRIVE_STATUS_WORD],       pDst := ADR(_stStatus.DriveStatusWord),     udiSize := SIZEOF(_stStatus.DriveStatusWord)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_DEVICE_ERROR_CODE],       pDst := ADR(_stStatus.DeviceErrorCode),     udiSize := SIZEOF(_stStatus.DeviceErrorCode)) AND _bCopyOk;
            _bCopyOk := Fn_RtCopy(pData := _pData, udiDataSize := _udiSize, udiOffset := _stOfs.audiOffset[GVL_AxisRtMap.F_PLC_OPEN_STATE],          pDst := ADR(_stStatus.PlcOpenState),        udiSize := SIZEOF(_stStatus.PlcOpenState)) AND _bCopyOk;
            IF _bCopyOk THEN
                _bValid := TRUE;
            ELSE
                _eResult := DL_RESULT.DL_SIZE_MISMATCH;     // a field lies outside the buffer
            END_IF
        END_IF
        fbMem.EndAccess();
        _bError := NOT _bValid;
    END_IF
END_IF

// No good read: report the axis as not valid
IF NOT _bValid THEN
    _stStatus := _stCleared;
END_IF

// Outputs
IF _bIndexOk THEN
    astStatus[iAxis] := _stStatus;
END_IF
bValid    := _bValid;
bError    := _bError;
bNotInMap := _bNotInMap;
eResult   := _eResult;

InterfaceAsPlainText.xhtml:
FUNCTION_BLOCK FB_ServoAxisMgr
VAR_INPUT
    itfClient   : I_StateClient;                        // GVL_State.aClients[GVL_State.CLIENT_SERVO_AXES]
    eMachineState : E_MachineState;   // machine state to follow (from the caller: the broadcast, or a sub-manager's state)
    asAxisName  : ARRAY[0..GVL_Axes.LAST_AXIS] OF STRING(15);    // ctrlX MOTION axis names: Ax1, Ax2, VM
END_VAR
VAR_IN_OUT CONSTANT
    astStatus   : ARRAY[0..GVL_Axes.LAST_AXIS] OF ST_AxisCyclicStatus;   // cyclic axis status
END_VAR
VAR_OUTPUT
    bAllPowered : BOOL;     // diag: all axes powered
    bAllOff     : BOOL;     // diag: all axes torque-free
    bAllAtRest  : BOOL;     // diag: all axes at rest (debounced)
    bAnyError   : BOOL;     // diag: some axis has an error
    uiAbortCode : UINT;     // abort code currently requested, 0 = none
END_VAR
VAR
    _eMachineState      : E_MachineState;
    _eLastMachineState  : E_MachineState;
    _iAxis              : INT;

    _bAllPowered        : BOOL;
    _bAllOff            : BOOL;
    _bAllAtRestNow      : BOOL;     // undebounced
    _bAnyError          : BOOL;
    _abPowerReady       : ARRAY[0..GVL_Axes.LAST_AXIS] OF BOOL;     // motion reports the axis ready for power up
    _abPowerConfirmed   : ARRAY[0..GVL_Axes.LAST_AXIS] OF BOOL;     // axis reported PowerOn since power was commanded
    _abCmdRejected      : ARRAY[0..GVL_Axes.LAST_AXIS] OF BOOL;     // an ML_ command was not accepted; cleared on entry to Resetting

    _bFaultAbortActive  : BOOL;
    _bAbort             : BOOL;
    _uiAbortCode        : UINT;
    _bDone              : BOOL;

    _bWantPower         : BOOL;     // machine-level power want (before per-axis conditions)
    _abWantPower        : ARRAY[0..GVL_Axes.LAST_AXIS] OF BOOL;
    _abPowerSent        : ARRAY[0..GVL_Axes.LAST_AXIS] OF BOOL;     // last power level commanded per axis
    _astPower           : ARRAY[0..GVL_Axes.LAST_AXIS] OF ML_AxsPowerData;
    _astReset           : ARRAY[0..GVL_Axes.LAST_AXIS] OF ML_AxsResetData;

    _fbRestDebounce     : TON;
    _fbStateReq         : FB_StateRequest;
END_VAR
VAR CONSTANT
    REST_DEBOUNCE       : TIME := T#100MS;          // all axes must be at rest this long before going torque-free
    SOURCE_NAME         : STRING(50) := 'FB_ServoAxisMgr';
    ABORT_NONE          : UINT := 0;
    ABORT_AXIS_ERROR    : UINT := 200;  // + axis index
    ABORT_POWER_LOST    : UINT := 210;  // + axis index
    ABORT_AXIS_CMD      : UINT := 220;  // + axis index: power/reset command not accepted
    ABORT_AXIS_DATA     : UINT := 230;  // + axis index: cyclic status not valid
END_VAR

ST.xhtml:
_eMachineState := eMachineState;     // read once per scan

// ===== 1. Read status =====
_bAllPowered   := TRUE;
_bAllOff       := TRUE;
_bAllAtRestNow := TRUE;
_bAnyError     := FALSE;
FOR _iAxis := 0 TO GVL_Axes.LAST_AXIS DO
    // Readiness from the motion feedback, not the drive status word: it also works for an axis
    // switched to a virtual/test axis. The drive word belongs to the drive hardware station.
    _abPowerReady[_iAxis]      := astStatus[_iAxis].PowerReady;
    _abPowerConfirmed[_iAxis]  := _abPowerSent[_iAxis]
                                  AND (_abPowerConfirmed[_iAxis] OR astStatus[_iAxis].PowerOn);

    _bAllPowered   := _bAllPowered AND astStatus[_iAxis].PowerOn;
    _bAllOff       := _bAllOff AND NOT astStatus[_iAxis].PowerOn;
    // At rest: standstill, disabled or in error (an axis in error is stopped by its drive)
    _bAllAtRestNow := _bAllAtRestNow AND (astStatus[_iAxis].Standstill
                                          OR NOT astStatus[_iAxis].PowerOn
                                          OR astStatus[_iAxis].HasError);
    _bAnyError     := _bAnyError OR astStatus[_iAxis].HasError;
END_FOR

// ===== 2. Faults -> abort request =====
// Not raised while aborting, aborted or resetting, so a fault can't block its own reset.
_bFaultAbortActive := _eMachineState <> E_MachineState.Aborting
                      AND _eMachineState <> E_MachineState.Aborted
                      AND _eMachineState <> E_MachineState.Resetting;

_uiAbortCode := ABORT_NONE;
FOR _iAxis := 0 TO GVL_Axes.LAST_AXIS DO
    IF _uiAbortCode = ABORT_NONE THEN
        IF NOT astStatus[_iAxis].DataValid THEN
            _uiAbortCode := ABORT_AXIS_DATA + INT_TO_UINT(_iAxis);
        ELSIF astStatus[_iAxis].HasError THEN
            _uiAbortCode := ABORT_AXIS_ERROR + INT_TO_UINT(_iAxis);
        ELSIF _abPowerConfirmed[_iAxis] AND NOT astStatus[_iAxis].PowerOn THEN
            _uiAbortCode := ABORT_POWER_LOST + INT_TO_UINT(_iAxis);
        ELSIF _abCmdRejected[_iAxis] THEN
            _uiAbortCode := ABORT_AXIS_CMD + INT_TO_UINT(_iAxis);
        END_IF
    END_IF
END_FOR
_bAbort := _bFaultAbortActive AND _uiAbortCode <> ABORT_NONE;

// ===== 3. Done for the current machine state =====
CASE _eMachineState OF
    E_MachineState.Off, E_MachineState.Aborted, E_MachineState.Aborting:
        _bDone := _bAllOff;                         // Aborting: torque-free before the supply goes off

    E_MachineState.TurningOn, E_MachineState.Resetting:
        _bDone := _bAllPowered AND NOT _bAnyError;

ELSE
    _bDone := TRUE;                                 // stay powered, nothing else to do
END_CASE

// ===== 4. On change of machine state: reset on entry to Resetting =====
IF _eMachineState <> _eLastMachineState THEN
    IF _eMachineState = E_MachineState.Resetting THEN
        // Any fault aborts, so Resetting always follows one: reset every axis unconditionally.
        // Drive 0 (Ax1) hosts the drive supply, so this also clears supply errors.
        FOR _iAxis := 0 TO GVL_Axes.LAST_AXIS DO
            _abCmdRejected[_iAxis] := FALSE;
            _astReset[_iAxis].In.AxisName := asAxisName[_iAxis];
            _astReset[_iAxis].In.Source   := SOURCE_NAME;
            IF NOT ML_AxsReset(Data := _astReset[_iAxis]) THEN
                _abCmdRejected[_iAxis] := TRUE;
            END_IF
        END_FOR
    END_IF
    _eLastMachineState := _eMachineState;
END_IF

// ===== 5. Command levels: power per axis =====
// Powered in every state except Off and Aborted; in Aborting only until all axes are at rest
_bWantPower := _eMachineState <> E_MachineState.Off
               AND _eMachineState <> E_MachineState.Aborted
               AND NOT (_eMachineState = E_MachineState.Aborting AND _fbRestDebounce.Q);

FOR _iAxis := 0 TO GVL_Axes.LAST_AXIS DO
    // Enable only once the drive's power section is ready (DC bus up) and the axis has no error
    _abWantPower[_iAxis] := _bWantPower AND _abPowerReady[_iAxis] AND NOT astStatus[_iAxis].HasError;

    // ML_AxsPower is one-shot: issue it once each time the wanted level changes
    IF _abWantPower[_iAxis] <> _abPowerSent[_iAxis] THEN
        _astPower[_iAxis].In.AxisName := asAxisName[_iAxis];
        _astPower[_iAxis].In.Source   := SOURCE_NAME;
        _astPower[_iAxis].In.SwitchOn := _abWantPower[_iAxis];
        IF NOT ML_AxsPower(Data := _astPower[_iAxis]) THEN
            _abCmdRejected[_iAxis] := TRUE;
        END_IF
        _abPowerSent[_iAxis] := _abWantPower[_iAxis];
    END_IF
END_FOR

// ===== 6. Outputs, then sub-FBs =====
bAllPowered := _bAllPowered;
bAllOff     := _bAllOff;
bAllAtRest  := _fbRestDebounce.Q;
bAnyError   := _bAnyError;
uiAbortCode := _uiAbortCode;

_fbRestDebounce(IN := _bAllAtRestNow, PT := REST_DEBOUNCE);
_fbStateReq(
    itfClient   := itfClient,
    bAbort      := _bAbort,
    uiAbortCode := _uiAbortCode,
    eStateEcho  := _eMachineState,
    bDone       := _bDone);

InterfaceAsPlainText.xhtml:
FUNCTION_BLOCK FB_ServoMotionSeq
VAR_INPUT
    itfClient   : I_StateClient;                                // GVL_State.aClients[GVL_State.CLIENT_SERVO_MOTION]
    eMachineState : E_MachineState;   // machine state to follow (from the caller: the broadcast, or a sub-manager's state)
    asAxisName  : ARRAY[0..GVL_Axes.LAST_AXIS] OF STRING(15);   // ctrlX MOTION axis names: Ax1, Ax2, VM
    lrSpeedCmd  : LREAL;    // VM velocity in Running; limited by the caller; may change at any time
    lrAx1Offset : LREAL;    // Ax1 phase offset from the VM (positioning target and gear slave offset)
    lrAx2Offset : LREAL;    // Ax2 phase offset from the VM (positioning target and gear slave offset)
END_VAR
VAR_IN_OUT CONSTANT
    astStatus   : ARRAY[0..GVL_Axes.LAST_AXIS] OF ST_AxisCyclicStatus;   // cyclic axis status
END_VAR
VAR_OUTPUT
    eSeqState   : E_ServoSeqState;  // current step, for HMI / online view
    uiAbortCode : UINT;             // abort code currently requested, 0 = none
END_VAR
VAR
    _eMachineState  : E_MachineState;
    _eSeqState      : E_ServoSeqState;
    _eLastSeqState  : E_ServoSeqState;
    _iAxis          : INT;
    _lrSpeedLatched : LREAL;        // speed of the velocity command currently running

    // Command tracking, one command per axis at a time
    _abTrack        : ARRAY[0..GVL_Axes.LAST_AXIS] OF BOOL;
    _abAccepted     : ARRAY[0..GVL_Axes.LAST_AXIS] OF BOOL;
    _aulCmdID       : ARRAY[0..GVL_Axes.LAST_AXIS] OF ULINT;
    _afbCmd         : ARRAY[0..GVL_Axes.LAST_AXIS] OF FB_AxisCmdState;
    _iFailedAxis    : INT;

    // ML_ command data
    _astPosAbs      : ARRAY[0..GVL_Axes.LAST_AXIS] OF ML_AxsPosData;
    _astGearIn      : ARRAY[0..GVL_Axes.LAST_AXIS] OF ML_AxsGearInPos2Data;    // used for Ax1, Ax2
    _stVmVel        : ML_AxsVelData;
    _astAbort       : ARRAY[0..GVL_Axes.LAST_AXIS] OF ML_AxsAbortData;

    _bFaultAbortActive : BOOL;
    _bAbort         : BOOL;
    _uiAbortCode    : UINT;
    _bDone          : BOOL;
    _fbStateReq     : FB_StateRequest;
END_VAR
VAR CONSTANT
    NO_AXIS         : INT := -1;
    VM_POSITION     : LREAL := 0.0;     // VM start position
    POS_VEL         : LREAL := 90.0;    // start positioning: velocity (units/s)   -- set for the machine
    POS_ACC         : LREAL := 360.0;   // start positioning: acceleration
    POS_DEC         : LREAL := 360.0;   // start positioning and ungearing: deceleration
    VM_ACC          : LREAL := 360.0;   // VM ramp up
    VM_DEC          : LREAL := 360.0;   // VM normal ramp down (hold, stop)
    ABORT_DEC       : LREAL := 1440.0;  // abort deceleration, separate from VM_DEC
    NO_JERK_LIMIT   : LREAL := 0.0;     // jerk 0 on both = no jerk limit (trapezoid)
    SPEED_DEADBAND  : LREAL := 0.01;    // speed command change that re-issues the VM velocity
    GEAR_RATIO      : DINT := 1;        // 1:1
    MASTER_OFFSET   : LREAL := 0.0;
    MASTER_SYNC_POS : LREAL := 0.0;
    MASTER_START_DIST : LREAL := 0.0;
    FINE_ADJUST     : LREAL := 0.0;
    SOURCE_NAME     : STRING(50) := 'FB_ServoMotionSeq';
    ABORT_NONE      : UINT := 0;
    ABORT_MOTION_CMD: UINT := 300;      // + axis index: motion command rejected, aborted or failed
    ABORT_SEQ_INVALID : UINT := 399;    // unknown sequence state
END_VAR

ST.xhtml:
_eMachineState := eMachineState;     // read once per scan

// ===== 1. Jumps: abort first, then stop =====
IF _eMachineState = E_MachineState.Aborting THEN
    // From any active step: stop the VM first (slaves follow while geared)
    IF _eSeqState <> E_ServoSeqState.AbortVm
       AND _eSeqState <> E_ServoSeqState.AbortSlaves
       AND _eSeqState <> E_ServoSeqState.Idle THEN
        _eSeqState := E_ServoSeqState.AbortVm;
    END_IF
ELSIF _eMachineState = E_MachineState.Stopping THEN
    // From any active step not already on the stop (or abort) path: halt the VM, then ungear
    IF _eSeqState <> E_ServoSeqState.Idle
       AND _eSeqState <> E_ServoSeqState.VmHalting
       AND _eSeqState <> E_ServoSeqState.Ungearing
       AND _eSeqState <> E_ServoSeqState.AbortVm
       AND _eSeqState <> E_ServoSeqState.AbortSlaves THEN
        _eSeqState := E_ServoSeqState.VmHalting;
    END_IF
END_IF

// ===== 2. Transitions only =====
CASE _eSeqState OF
    E_ServoSeqState.Idle:
        IF _eMachineState = E_MachineState.Starting THEN
            _eSeqState := E_ServoSeqState.Positioning;
        END_IF

    E_ServoSeqState.Positioning:
        IF _afbCmd[GVL_Axes.AX1].bDone AND _afbCmd[GVL_Axes.AX2].bDone AND _afbCmd[GVL_Axes.VM].bDone THEN
            _eSeqState := E_ServoSeqState.GearingIn;
        END_IF

    E_ServoSeqState.GearingIn:
        IF astStatus[GVL_Axes.AX1].InSynchronization AND astStatus[GVL_Axes.AX2].InSynchronization THEN
            _eSeqState := E_ServoSeqState.Synced;
        END_IF

    E_ServoSeqState.Synced:
        IF _eMachineState = E_MachineState.Running OR _eMachineState = E_MachineState.UnHolding THEN
            _eSeqState := E_ServoSeqState.VmRunning;
        END_IF

    E_ServoSeqState.VmRunning:
        IF _eMachineState = E_MachineState.Holding THEN
            _eSeqState := E_ServoSeqState.VmHalting;
        ELSIF ABS(lrSpeedCmd - _lrSpeedLatched) > SPEED_DEADBAND THEN
            _eSeqState := E_ServoSeqState.VmSpeedChange;
        END_IF

    E_ServoSeqState.VmSpeedChange:
        // Back to VmRunning: its entry issues the velocity command with the new speed
        _eSeqState := E_ServoSeqState.VmRunning;

    E_ServoSeqState.VmHalting:
        IF _afbCmd[GVL_Axes.VM].bDone THEN
            IF _eMachineState = E_MachineState.Stopping THEN
                _eSeqState := E_ServoSeqState.Ungearing;
            ELSE
                _eSeqState := E_ServoSeqState.Synced;   // Holding: VM stopped, slaves stay geared
            END_IF
        END_IF

    E_ServoSeqState.Ungearing:
        IF _afbCmd[GVL_Axes.AX1].bDone AND _afbCmd[GVL_Axes.AX2].bDone THEN
            _eSeqState := E_ServoSeqState.Idle;
        END_IF

    E_ServoSeqState.AbortVm:
        // Stopped, or can't be commanded any more (unpowered / in error): move on, never hang
        IF _afbCmd[GVL_Axes.VM].bDone OR _afbCmd[GVL_Axes.VM].bFailed
           OR NOT astStatus[GVL_Axes.VM].PowerOn OR astStatus[GVL_Axes.VM].HasError THEN
            _eSeqState := E_ServoSeqState.AbortSlaves;
        END_IF

    E_ServoSeqState.AbortSlaves:
        IF (_afbCmd[GVL_Axes.AX1].bDone OR _afbCmd[GVL_Axes.AX1].bFailed
            OR NOT astStatus[GVL_Axes.AX1].PowerOn OR astStatus[GVL_Axes.AX1].HasError)
           AND (_afbCmd[GVL_Axes.AX2].bDone OR _afbCmd[GVL_Axes.AX2].bFailed
            OR NOT astStatus[GVL_Axes.AX2].PowerOn OR astStatus[GVL_Axes.AX2].HasError) THEN
            _eSeqState := E_ServoSeqState.Idle;
        END_IF

ELSE
    _eSeqState := E_ServoSeqState.AbortVm;
END_CASE

// ===== 3. On change: common actions, then entry actions (ML_ commands issued here, once) =====
IF _eSeqState <> _eLastSeqState THEN
    // Every change: stop tracking the previous step's commands
    FOR _iAxis := 0 TO GVL_Axes.LAST_AXIS DO
        _abTrack[_iAxis]    := FALSE;
        _abAccepted[_iAxis] := FALSE;
    END_FOR

    CASE _eSeqState OF
        E_ServoSeqState.Positioning:
            // Absolute moves, shortest way on the modulo axes
            _astPosAbs[GVL_Axes.AX1].In.Position := lrAx1Offset;
            _astPosAbs[GVL_Axes.AX2].In.Position := lrAx2Offset;
            _astPosAbs[GVL_Axes.VM].In.Position  := VM_POSITION;
            FOR _iAxis := 0 TO GVL_Axes.LAST_AXIS DO
                _astPosAbs[_iAxis].In.AxisName := asAxisName[_iAxis];
                _astPosAbs[_iAxis].In.Source   := SOURCE_NAME;
                _astPosAbs[_iAxis].In.Buffered := TRUE;
                _astPosAbs[_iAxis].In.DynLimits.Velocity     := POS_VEL;
                _astPosAbs[_iAxis].In.DynLimits.Acceleration := POS_ACC;
                _astPosAbs[_iAxis].In.DynLimits.Deceleration := POS_DEC;
                _astPosAbs[_iAxis].In.DynLimits.JerkAcc      := NO_JERK_LIMIT;
                _astPosAbs[_iAxis].In.DynLimits.JerkDec      := NO_JERK_LIMIT;
                _abAccepted[_iAxis] := ML_AxsPosAbs(Data := _astPosAbs[_iAxis]);
                _aulCmdID[_iAxis]   := _astPosAbs[_iAxis].Out.CmdID;
                _abTrack[_iAxis]    := TRUE;
            END_FOR

        E_ServoSeqState.GearingIn:
            // Absolute to the VM set point: slave = VM x 1 + slave offset, synchronised the shortest way
            _astGearIn[GVL_Axes.AX1].In.Parameters.SlaveOffset := lrAx1Offset;
            _astGearIn[GVL_Axes.AX2].In.Parameters.SlaveOffset := lrAx2Offset;
            FOR _iAxis := GVL_Axes.AX1 TO GVL_Axes.AX2 DO
                _astGearIn[_iAxis].In.AxisName            := asAxisName[_iAxis];
                _astGearIn[_iAxis].In.Source              := SOURCE_NAME;
                _astGearIn[_iAxis].In.MasterName          := asAxisName[GVL_Axes.VM];
                _astGearIn[_iAxis].In.SyncSource          := ML_SyncSource.SYNC_SETPOINT;
                _astGearIn[_iAxis].In.SyncMode            := ML_SyncMode.SYNC_ABSOLUTE;
                _astGearIn[_iAxis].In.DynSyncDirection    := ML_DynSyncDirection.SHORTEST_WAY;
                _astGearIn[_iAxis].In.MasterSyncPosition  := MASTER_SYNC_POS;
                _astGearIn[_iAxis].In.MasterStartDistance := MASTER_START_DIST;
                _astGearIn[_iAxis].In.Parameters.MasterOffset     := MASTER_OFFSET;
                _astGearIn[_iAxis].In.Parameters.RatioNumerator   := GEAR_RATIO;
                _astGearIn[_iAxis].In.Parameters.RatioDenominator := GEAR_RATIO;
                _astGearIn[_iAxis].In.Parameters.FineAdjust       := FINE_ADJUST;
                _astGearIn[_iAxis].In.Buffered            := TRUE;
                _abAccepted[_iAxis] := ML_AxsGearInPos2(Data := _astGearIn[_iAxis]);
                _aulCmdID[_iAxis]   := _astGearIn[_iAxis].Out.CmdID;
                _abTrack[_iAxis]    := TRUE;
            END_FOR

        E_ServoSeqState.VmRunning:
            // Unbuffered, so a new speed replaces the running command without stopping the VM
            _lrSpeedLatched := lrSpeedCmd;
            _stVmVel.In.AxisName := asAxisName[GVL_Axes.VM];
            _stVmVel.In.Source   := SOURCE_NAME;
            _stVmVel.In.Velocity := _lrSpeedLatched;
            _stVmVel.In.DriveVelMode := FALSE;
            _stVmVel.In.Buffered := FALSE;
            _stVmVel.In.DynLimits.Velocity     := ABS(_lrSpeedLatched);
            _stVmVel.In.DynLimits.Acceleration := VM_ACC;
            _stVmVel.In.DynLimits.Deceleration := VM_DEC;
            _stVmVel.In.DynLimits.JerkAcc      := NO_JERK_LIMIT;
            _stVmVel.In.DynLimits.JerkDec      := NO_JERK_LIMIT;
            _abAccepted[GVL_Axes.VM] := ML_AxsVelocity(Data := _stVmVel);
            _aulCmdID[GVL_Axes.VM]   := _stVmVel.Out.CmdID;
            _abTrack[GVL_Axes.VM]    := TRUE;

        E_ServoSeqState.VmHalting:
            _astAbort[GVL_Axes.VM].In.AxisName     := asAxisName[GVL_Axes.VM];
            _astAbort[GVL_Axes.VM].In.Source       := SOURCE_NAME;
            _astAbort[GVL_Axes.VM].In.Deceleration := VM_DEC;
            _astAbort[GVL_Axes.VM].In.JerkDec      := NO_JERK_LIMIT;
            _abAccepted[GVL_Axes.VM] := ML_AxsAbort(Data := _astAbort[GVL_Axes.VM]);
            _aulCmdID[GVL_Axes.VM]   := _astAbort[GVL_Axes.VM].Out.CmdID;
            _abTrack[GVL_Axes.VM]    := TRUE;

        E_ServoSeqState.Ungearing:
            // Slaves are already at zero speed with the VM: cancelling the gearing brings them to standstill
            FOR _iAxis := GVL_Axes.AX1 TO GVL_Axes.AX2 DO
                _astAbort[_iAxis].In.AxisName     := asAxisName[_iAxis];
                _astAbort[_iAxis].In.Source       := SOURCE_NAME;
                _astAbort[_iAxis].In.Deceleration := POS_DEC;
                _astAbort[_iAxis].In.JerkDec      := NO_JERK_LIMIT;
                _abAccepted[_iAxis] := ML_AxsAbort(Data := _astAbort[_iAxis]);
                _aulCmdID[_iAxis]   := _astAbort[_iAxis].Out.CmdID;
                _abTrack[_iAxis]    := TRUE;
            END_FOR

        E_ServoSeqState.AbortVm:
            // Slaves follow the VM down while still geared
            _astAbort[GVL_Axes.VM].In.AxisName     := asAxisName[GVL_Axes.VM];
            _astAbort[GVL_Axes.VM].In.Source       := SOURCE_NAME;
            _astAbort[GVL_Axes.VM].In.Deceleration := ABORT_DEC;
            _astAbort[GVL_Axes.VM].In.JerkDec      := NO_JERK_LIMIT;
            _abAccepted[GVL_Axes.VM] := ML_AxsAbort(Data := _astAbort[GVL_Axes.VM]);
            _aulCmdID[GVL_Axes.VM]   := _astAbort[GVL_Axes.VM].Out.CmdID;
            _abTrack[GVL_Axes.VM]    := TRUE;

        E_ServoSeqState.AbortSlaves:
            FOR _iAxis := GVL_Axes.AX1 TO GVL_Axes.AX2 DO
                _astAbort[_iAxis].In.AxisName     := asAxisName[_iAxis];
                _astAbort[_iAxis].In.Source       := SOURCE_NAME;
                _astAbort[_iAxis].In.Deceleration := ABORT_DEC;
                _astAbort[_iAxis].In.JerkDec      := NO_JERK_LIMIT;
                _abAccepted[_iAxis] := ML_AxsAbort(Data := _astAbort[_iAxis]);
                _aulCmdID[_iAxis]   := _astAbort[_iAxis].Out.CmdID;
                _abTrack[_iAxis]    := TRUE;
            END_FOR
    END_CASE

    _eLastSeqState := _eSeqState;
END_IF

// ===== 4. Cyclic =====
// Faults -> abort request. Command failures in the abort steps are expected (axes may be
// unpowered or in error) and don't count. Not raised while aborting, aborted or resetting.
_bFaultAbortActive := _eMachineState <> E_MachineState.Aborting
                      AND _eMachineState <> E_MachineState.Aborted
                      AND _eMachineState <> E_MachineState.Resetting;
_iFailedAxis := NO_AXIS;
IF _eSeqState <> E_ServoSeqState.AbortVm AND _eSeqState <> E_ServoSeqState.AbortSlaves THEN
    FOR _iAxis := 0 TO GVL_Axes.LAST_AXIS DO
        IF _afbCmd[_iAxis].bFailed AND _iFailedAxis = NO_AXIS THEN
            _iFailedAxis := _iAxis;
        END_IF
    END_FOR
END_IF
IF _iFailedAxis <> NO_AXIS THEN
    _uiAbortCode := ABORT_MOTION_CMD + INT_TO_UINT(_iFailedAxis);
ELSE
    _uiAbortCode := ABORT_NONE;
END_IF
_bAbort := _bFaultAbortActive AND _uiAbortCode <> ABORT_NONE;

// Done for the current machine state, from the sequence state
CASE _eMachineState OF
    E_MachineState.Starting, E_MachineState.Holding:
        _bDone := _eSeqState = E_ServoSeqState.Synced;

    E_MachineState.UnHolding:
        _bDone := _eSeqState = E_ServoSeqState.VmRunning AND astStatus[GVL_Axes.VM].InVelocity;

    E_MachineState.Stopping, E_MachineState.Aborting:
        _bDone := _eSeqState = E_ServoSeqState.Idle;

ELSE
    _bDone := TRUE;     // no motion work in this machine state
END_CASE

// Outputs
eSeqState   := _eSeqState;
uiAbortCode := _uiAbortCode;

// Sub-FBs: command trackers and the state client, every scan
FOR _iAxis := 0 TO GVL_Axes.LAST_AXIS DO
    _afbCmd[_iAxis](
        bActive   := _abTrack[_iAxis],
        sObjName  := asAxisName[_iAxis],
        ulCmdID   := _aulCmdID[_iAxis],
        bAccepted := _abAccepted[_iAxis]);
END_FOR
_fbStateReq(
    itfClient   := itfClient,
    bAbort      := _bAbort,
    uiAbortCode := _uiAbortCode,
    eStateEcho  := _eMachineState,
    bDone       := _bDone);

Fn_RtCopy := pData <> 0 AND pDst <> 0 AND udiOffset + udiSize <= udiDataSize;
IF Fn_RtCopy THEN
    _pSrc := pData + udiOffset;
    _pDst := pDst;
    FOR _udiByte := 1 TO udiSize DO
        _pDst^ := _pSrc^;
        _pSrc := _pSrc + 1;
        _pDst := _pDst + 1;
    END_FOR
END_IF

InterfaceAsPlainText.xhtml:
FUNCTION_BLOCK FB_StateManager
VAR_IN_OUT
    aClients            : ARRAY[*] OF FB_StateClient;  // GVL_State.aClients; lower bound must be >= 1
END_VAR
VAR_OUTPUT
    eMachineState       : E_MachineState;   // the machine state
    uiAbortCode         : UINT;             // first abort cause, 0 = none
    iAbortClient        : DINT;             // client that caused the abort, 0 = none / manager
    eAbortFrom          : E_MachineState;   // state the machine aborted from
    bAbortUnacked       : BOOL;             // timeout abort: iAbortClient never acknowledged the state
    iAbortTimeoutClient : DINT;             // client that did not finish Aborting in time
    iNotDoneClient      : DINT;             // live: first client not done with the current state
END_VAR
VAR
    _eState             : E_MachineState;
    _eLastState         : E_MachineState;

    // Abort record: first cause only, cleared on entry to Idle
    _uiAbortCode        : UINT;
    _iAbortClient       : DINT;
    _eAbortFrom         : E_MachineState;
    _bAbortUnacked      : BOOL;
    _iAbortTimeoutClient: DINT;

    // Combined client data, rebuilt every scan
    _bReqOn             : BOOL;
    _bReqOff            : BOOL;
    _bReqStart          : BOOL;
    _bReqStop           : BOOL;
    _bReqHold           : BOOL;
    _bReqAbort          : BOOL;
    _bReqReset          : BOOL;
    _bAllDone           : BOOL;             // every enabled client is done with _eDoneState
    _eDoneState         : E_MachineState;   // state _bAllDone was evaluated for
    _iFirstAbortClient  : DINT;
    _uiFirstAbortCode   : UINT;
    _iFirstNotDone      : DINT;
    _bFirstNotDoneUnacked : BOOL;
    _iClient            : DINT;
    _stClient           : ST_StateClientData;

    _tStepTimeout       : TIME;             // timeout of the current state, T#0S = none
    _fbStepTimer        : TON;
END_VAR
VAR CONSTANT
    NO_CLIENT                : DINT := 0;
    ABORT_CODE_NONE          : UINT := 0;
    ABORT_CODE_TIMEOUT       : UINT := 16#FFF0;    // a transitional state timed out
    ABORT_CODE_INVALID_STATE : UINT := 16#FFFF;    // unknown state value (e.g. after online change)

    TURNING_ON_TIMEOUT  : TIME := T#30S;
    STARTING_TIMEOUT    : TIME := T#60S;
    STOPPING_TIMEOUT    : TIME := T#30S;
    HOLDING_TIMEOUT     : TIME := T#30S;
    UNHOLDING_TIMEOUT   : TIME := T#30S;
    ABORTING_TIMEOUT    : TIME := T#10S;
    RESETTING_TIMEOUT   : TIME := T#30S;
END_VAR

ST.xhtml:
// ===== 0. Read clients =====
_bReqOn    := FALSE;
_bReqOff   := FALSE;
_bReqStart := FALSE;
_bReqStop  := FALSE;
_bReqHold  := FALSE;
_bReqAbort := FALSE;
_bReqReset := FALSE;
_bAllDone  := TRUE;
_eDoneState := _eState;
_iFirstAbortClient    := NO_CLIENT;
_uiFirstAbortCode     := ABORT_CODE_NONE;
_iFirstNotDone        := NO_CLIENT;
_bFirstNotDoneUnacked := FALSE;

FOR _iClient := LOWER_BOUND(aClients, 1) TO UPPER_BOUND(aClients, 1) DO
    _stClient := aClients[_iClient].Data;
    IF _stClient.bEnabled THEN
        _bReqOn    := _bReqOn    OR _stClient.bOn;
        _bReqOff   := _bReqOff   OR _stClient.bOff;
        _bReqStart := _bReqStart OR _stClient.bStart;
        _bReqStop  := _bReqStop  OR _stClient.bStop;
        _bReqHold  := _bReqHold  OR _stClient.bHold;
        _bReqAbort := _bReqAbort OR _stClient.bAbort;
        _bReqReset := _bReqReset OR _stClient.bReset;

        IF _stClient.bAbort AND _iFirstAbortClient = NO_CLIENT THEN
            _iFirstAbortClient := _iClient;
            _uiFirstAbortCode  := _stClient.uiAbortCode;
        END_IF

        // Done only counts for the current state: a stale done from an old echo is ignored
        IF NOT (_stClient.eStateEcho = _eState AND _stClient.bDone) THEN
            _bAllDone := FALSE;
            IF _iFirstNotDone = NO_CLIENT THEN
                _iFirstNotDone        := _iClient;
                _bFirstNotDoneUnacked := _stClient.eStateEcho <> _eState;
            END_IF
        END_IF
    END_IF
END_FOR

// ===== 1. Jumps: abort, then timeout =====
IF _eState = E_MachineState.Aborting THEN
    // Reaching a resettable state matters more than waiting forever
    IF _fbStepTimer.Q THEN
        _iAbortTimeoutClient := _iFirstNotDone;
        _eState := E_MachineState.Aborted;
    END_IF
ELSIF _eState <> E_MachineState.Off AND _eState <> E_MachineState.Aborted THEN
    IF _bReqAbort THEN
        _uiAbortCode   := _uiFirstAbortCode;
        _iAbortClient  := _iFirstAbortClient;
        _bAbortUnacked := FALSE;
        _eAbortFrom    := _eState;
        _eState := E_MachineState.Aborting;
    ELSIF _fbStepTimer.Q THEN
        _uiAbortCode   := ABORT_CODE_TIMEOUT;
        _iAbortClient  := _iFirstNotDone;
        _bAbortUnacked := _bFirstNotDoneUnacked;
        _eAbortFrom    := _eState;
        _eState := E_MachineState.Aborting;
    END_IF
END_IF

// ===== 2. Transitions only =====
// _bAllDone was evaluated for _eDoneState (the state at the start of the scan). After a
// jump it says nothing about the new state, so every AllDone transition also checks that.
CASE _eState OF
    E_MachineState.Off:
        IF _bReqOn AND NOT _bReqOff THEN
            _eState := E_MachineState.TurningOn;
        END_IF

    E_MachineState.TurningOn:
        IF _bAllDone AND _eDoneState = _eState THEN
            _eState := E_MachineState.Idle;
        END_IF

    E_MachineState.Idle:
        IF _bReqOff THEN
            _eState := E_MachineState.Off;
        ELSIF _bReqStart AND NOT _bReqStop THEN
            _eState := E_MachineState.Starting;
        END_IF

    E_MachineState.Starting:
        // A stop always wins, whether or not starting has completed
        IF _bReqStop THEN
            _eState := E_MachineState.Stopping;
        ELSIF _bAllDone AND _eDoneState = _eState THEN
            _eState := E_MachineState.Running;
        END_IF

    E_MachineState.Running:
        // Stop wins over hold
        IF _bReqStop THEN
            _eState := E_MachineState.Stopping;
        ELSIF _bReqHold THEN
            _eState := E_MachineState.Holding;
        END_IF

    E_MachineState.Stopping:
        IF _bAllDone AND _eDoneState = _eState THEN
            _eState := E_MachineState.Idle;
        END_IF

    E_MachineState.Holding:
        IF _bAllDone AND _eDoneState = _eState THEN
            _eState := E_MachineState.Hold;
        END_IF

    E_MachineState.Hold:
        // Resume only when no client requests hold any more
        IF NOT _bReqHold THEN
            _eState := E_MachineState.UnHolding;
        END_IF

    E_MachineState.UnHolding:
        IF _bAllDone AND _eDoneState = _eState THEN
            _eState := E_MachineState.Running;
        END_IF

    E_MachineState.Aborting:
        IF _bAllDone AND _eDoneState = _eState THEN
            _eState := E_MachineState.Aborted;
        END_IF

    E_MachineState.Aborted:
        // A held abort can't be reset away
        IF _bReqReset AND NOT _bReqAbort THEN
            _eState := E_MachineState.Resetting;
        END_IF

    E_MachineState.Resetting:
        IF _bAllDone AND _eDoneState = _eState THEN
            _eState := E_MachineState.Idle;
        END_IF

ELSE
    _uiAbortCode   := ABORT_CODE_INVALID_STATE;
    _iAbortClient  := NO_CLIENT;
    _bAbortUnacked := FALSE;
    _eAbortFrom    := _eState;
    _eState := E_MachineState.Aborting;
END_CASE

// ===== 3. On change: common actions, then entry actions =====
IF _eState <> _eLastState THEN
    // Every change: restart the step timer, no timeout unless the new state sets one
    _fbStepTimer(IN := FALSE);
    _tStepTimeout := T#0S;

    CASE _eState OF
        E_MachineState.Idle:
            // Idle means nothing is wrong: drop the abort record
            _uiAbortCode         := ABORT_CODE_NONE;
            _iAbortClient        := NO_CLIENT;
            _eAbortFrom          := E_MachineState.Off;
            _bAbortUnacked       := FALSE;
            _iAbortTimeoutClient := NO_CLIENT;

        E_MachineState.TurningOn:
            _tStepTimeout := TURNING_ON_TIMEOUT;

        E_MachineState.Starting:
            _tStepTimeout := STARTING_TIMEOUT;

        E_MachineState.Stopping:
            _tStepTimeout := STOPPING_TIMEOUT;

        E_MachineState.Holding:
            _tStepTimeout := HOLDING_TIMEOUT;

        E_MachineState.UnHolding:
            _tStepTimeout := UNHOLDING_TIMEOUT;

        E_MachineState.Aborting:
            _tStepTimeout := ABORTING_TIMEOUT;

        E_MachineState.Resetting:
            _tStepTimeout := RESETTING_TIMEOUT;
    END_CASE

    _eLastState := _eState;
END_IF

// ===== 4. Cyclic: outputs, then sub-FBs =====
eMachineState       := _eState;
uiAbortCode         := _uiAbortCode;
iAbortClient        := _iAbortClient;
eAbortFrom          := _eAbortFrom;
bAbortUnacked       := _bAbortUnacked;
iAbortTimeoutClient := _iAbortTimeoutClient;
iNotDoneClient      := _iFirstNotDone;

_fbStepTimer(IN := _tStepTimeout > T#0S, PT := _tStepTimeout);

_bAttached := itfClient <> 0;
IF _bAttached THEN itfClient.Request( bOn := bOn, bOff := bOff, bStart := bStart, bStop := bStop, bHold := bHold, bAbort := bAbort, uiAbortCode := uiAbortCode, bReset := bReset); itfClient.Report( eStateEcho := eStateEcho, bDone := bDone, bEnable := bEnable); END_IF
// Outputs bAttached := _bAttached;

InterfaceAsPlainText.xhtml:
// GVL: GVL_IO
// Hardware signals. Map these in the device tree I/O mapping (EtherCAT SoE cyclic data).
{attribute 'qualified_only'}
VAR_GLOBAL CONSTANT
    NUM_DRIVES              : DINT := 2;    // drives in use on the supply (the spare drive 2 is not counted)
    DRIVE_AX1               : DINT := 0;    // drive 0: Ax1, also hosts the supply unit
    DRIVE_AX2               : DINT := 1;    // drive 1: Ax2
END_VAR
VAR_GLOBAL
    // Supply unit (drive-integrated)
    wDI_SupplyStatus        : WORD;                             // AT: S-0-2058 (S-0-1720.0.2) supply unit status word
    wDO_SupplyCtrl          : WORD;                             // MDT: S-0-2057 (S-0-1720.0.1) supply unit control word

    // Drives
    awDI_DriveStatus        : ARRAY[0..NUM_DRIVES - 1] OF WORD;     // AT: drive status word (bits 15/14 readiness, bit 13 fault)
    awDO_DriveDcBusCtrl     : ARRAY[0..NUM_DRIVES - 1] OF WORD;     // MDT: S-0-0240 DC bus power control

    // Drive 2: spare, not used yet. Not part of supply readiness, torque or fault checks.
    wDI_SpareDriveStatus    : WORD;                             // AT: drive 2 status word

    // Fault reset: drive 0 hosts the supply, so the servo axes' reset in Resetting also resets the supply
END_VAR

// GVL: GVL_Axes
// Servo station axes: names as configured in ctrlX MOTION, and their cyclic status
// (read from the Data Layer RT node by FB_AxisRtMap / FB_AxisRtRead in PRG_Main).
{attribute 'qualified_only'}
VAR_GLOBAL CONSTANT
    AX1         : INT := 0;     // real servo, drive 0 (also hosts the drive supply)
    AX2         : INT := 1;     // real servo, drive 1
    VM          : INT := 2;     // virtual master
    LAST_AXIS   : INT := 2;
    asAxisName  : ARRAY[0..LAST_AXIS] OF STRING(15) := ['Ax1', 'Ax2', 'VM'];  // set to the ctrlX MOTION axis names
END_VAR
VAR_GLOBAL
    astStatus   : ARRAY[0..LAST_AXIS] OF ST_AxisCyclicStatus;   // RT cyclic status, indexed AX1 / AX2 / VM, written by PRG_Main.afbAxisRtRead
END_VAR

// GVL: GVL_AxisRtMap
// Field table for the cyclic axis status RT node. FB_AxisRtMap looks each map entry
// '<axis>/<field>' up here; the F_* index is where its byte offset is stored in
// ST_AxisRtOffsets.audiOffset, and FB_AxisRtRead copies by the same index.
// Keep F_* and asFieldName in step: asFieldName[F_X] is the map name of field X.
{attribute 'qualified_only'}
VAR_GLOBAL CONSTANT
    NODE_NAME           : STRING(255) := 'motion/realtime/cyclicStatusData';   // RT node
    NAME_SEPARATOR      : STRING(1) := '/';     // map names are '<axis>/<field>'
    BITS_PER_BYTE       : UDINT := 8;           // map offsets are in bits

    F_ACTUAL_POS            : INT := 0;
    F_ACTUAL_VEL            : INT := 1;
    F_ACTUAL_TRQ            : INT := 2;
    F_ACTUAL_TRQ_PERCENT    : INT := 3;
    F_DEVICE_ERROR_CODE     : INT := 4;
    F_PLC_OPEN_STATE        : INT := 5;
    F_DRIVE_STATUS_WORD     : INT := 6;
    F_DATA_VALID            : INT := 7;
    F_HOMED                 : INT := 8;
    F_STANDSTILL            : INT := 9;
    F_POWER_READY           : INT := 10;
    F_POWER_ON              : INT := 11;
    F_HAS_ERROR             : INT := 12;
    F_HAS_WARNING           : INT := 13;
    F_AXIS_FOLLOW_COMMAND   : INT := 14;
    F_IN_POSITION           : INT := 15;
    F_IN_VELOCITY           : INT := 16;
    F_IN_TORQUE             : INT := 17;
    F_IN_SYNCHRONIZATION    : INT := 18;
    F_OVERRIDE_IS_ZERO      : INT := 19;
    F_TORQUE_CTRL_POS_VEL_LIM : INT := 20;
    F_TORQUE_CTRL_NEG_VEL_LIM : INT := 21;
    F_IN_SYNC_WINDOW        : INT := 22;
    LAST_FIELD              : INT := 22;

    asFieldName : ARRAY[0..LAST_FIELD] OF STRING(31) := [
        'ActualPos', 'ActualVel', 'ActualTRQ', 'ActualTRQPercent',
        'DeviceErrorCode', 'PlcOpenState', 'DriveStatusWord',
        'DataValid', 'Homed', 'Standstill', 'PowerReady', 'PowerOn', 'HasError', 'HasWarning',
        'AxisFollowCommand', 'InPosition', 'InVelocity', 'InTorque', 'InSynchronization',
        'OverrideIsZero', 'TorqueCtrlPosVelLim', 'TorqueCtrlNegVelLim', 'InSyncWindow'];
END_VAR

// GVL: GVL_State
// Client array, client indexes and the broadcast machine state.
// The broadcast values are written only by PRG_Main, from FB_StateManager's outputs.
{attribute 'qualified_only'}
VAR_GLOBAL CONSTANT
    MAX_CLIENTS         : DINT := 4;
    CLIENT_HMI          : DINT := 1;
    CLIENT_DRIVE_HW     : DINT := 2;
    CLIENT_SERVO_AXES   : DINT := 3;
    CLIENT_SERVO_MOTION : DINT := 4;
END_VAR
VAR_GLOBAL
    aClients            : ARRAY[1..MAX_CLIENTS] OF FB_StateClient;  // index 0 is reserved for "no client"

    // Broadcast (copies of FB_StateManager outputs)
    eMachineState       : E_MachineState;   // the machine state every unit follows
    uiAbortCode         : UINT;             // first abort cause, 0 = none
    iAbortClient        : DINT;             // client that caused the abort, 0 = none / manager
    eAbortFrom          : E_MachineState;   // state the machine aborted from
    bAbortUnacked       : BOOL;             // timeout abort: iAbortClient never acknowledged the state
    iAbortTimeoutClient : DINT;             // client that did not finish Aborting in time, 0 = none
    iNotDoneClient      : DINT;             // live: first client not done with the current state
END_VAR
